-- Migration 107 (up): the one pass that restores garbled characters in the posts already stored (internal/textfix; new writes are restored as they arrive). text_repair is where the pass has reached, so it resumes after a restart and never runs twice; text_repair_lost names the posts it found characters in that could not be restored, for the Posts page to list until each is fixed by hand. NOTE: runMigrations executes line-by-line, so keep each statement on ONE line.
CREATE TABLE IF NOT EXISTS text_repair(id INTEGER PRIMARY KEY CHECK(id=1), cursor TEXT NOT NULL DEFAULT '', scanned INTEGER NOT NULL DEFAULT 0, restored INTEGER NOT NULL DEFAULT 0, done_at DATETIME);
CREATE TABLE IF NOT EXISTS text_repair_lost(slug TEXT PRIMARY KEY, runs INTEGER NOT NULL, found_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
